import React, { useState, useEffect } from "react";
import axios from "axios";

const Orders = () => {
  const [allOrders, setAllOrders] = useState([]);
  const [editingId, setEditingId] = useState(null); // Track kaunsa order edit ho raha hai
  const [editData, setEditData] = useState({ qty: 0, price: 0 }); // Temporary data for input

  useEffect(() => {
    fetchOrders();
  }, []);

  const fetchOrders = () => {
    axios.get("http://localhost:8080/allOrders").then((res) => {
      setAllOrders(res.data);
    });
  };

  const handleDelete = async (id) => {
    if (window.confirm("Kya aap is order ko delete karna chahte hain?")) {
      try {
        await axios.delete(`http://localhost:8080/deleteOrder/${id}`);
        setAllOrders(allOrders.filter((order) => order._id !== id));
      } catch (err) {
        alert("Delete error!");
      }
    }
  };

  const startEdit = (order) => {
    setEditingId(order._id);
    setEditData({ qty: order.qty, price: order.price });
  };

  const handleSave = async (id) => {
    try {
      await axios.put(`http://localhost:8080/updateOrder/${id}`, editData);
      setEditingId(null);
      fetchOrders(); // Naya data load karne ke liye
    } catch (err) {
      alert("Update fail!");
    }
  };

  return (
    <div className="orders">
      {allOrders.length === 0 ? (
        <p>No orders placed yet.</p>
      ) : (
        <div className="order-table">
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ borderBottom: "1px solid #eee", textAlign: "left" }}>
                <th>Instrument</th>
                <th>Qty.</th>
                <th>Price</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {allOrders.map((order) => {
                const isEditing = editingId === order._id;
                const isBuy = order.mode === "BUY";

                return (
                  <tr key={order._id} style={{ borderBottom: "1px solid #f9f9f9", height: "50px" }}>
                    <td>{order.name}</td>

                    {/* Qty Column: Normal text or Input */}
                    <td>
                      {isEditing ? (
                        <input
                          type="number"
                          value={editData.qty}
                          onChange={(e) => setEditData({ ...editData, qty: e.target.value })}
                          style={{ width: "60px" }}
                        />
                      ) : (
                        order.qty
                      )}
                    </td>

                    {/* Price Column: Normal text or Input */}
                    <td>
                      {isEditing ? (
                        <input
                          type="number"
                          value={editData.price}
                          onChange={(e) => setEditData({ ...editData, price: e.target.value })}
                          style={{ width: "80px" }}
                        />
                      ) : (
                        order.price.toFixed(2)
                      )}
                    </td>

                    <td style={{ color: isBuy ? "#4184f3" : "#ff5722", fontWeight: "bold" }}>
                      {order.mode}
                    </td>

                    {/* Actions Column: Save/Cancel or Edit/Delete */}
                    <td>
                      {isEditing ? (
                        <>
                          <button onClick={() => handleSave(order._id)} style={{ color: "green", marginRight: "5px" }}>Save</button>
                          <button onClick={() => setEditingId(null)}>Cancel</button>
                        </>
                      ) : (
                        <>
                          <button onClick={() => startEdit(order)} style={{ marginRight: "10px" }}>Edit</button>
                          <button onClick={() => handleDelete(order._id)} style={{ color: "red" }}>Delete</button>
                        </>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default Orders;
